import {ease} from './exit-route.js?v=60';
// Reuses the already decoded, independently recorded footstep PCM.
export function returnFootstep(audio,p){if(!audio.ctx||!audio.buffers.dirt)return false;const ctx=audio.ctx,t=ctx.currentTime,asphalt=1-ease(.15,.43,p),dirt=ease(.40,.65,p),sand=(1-asphalt)*(1-dirt),rate=.94+Math.random()*.09;for(const[k,w]of[['asphalt',asphalt],['gravel',sand],['dirt',dirt]]){if(w<.01)continue;const src=ctx.createBufferSource(),gain=ctx.createGain(),filter=ctx.createBiquadFilter();src.buffer=audio.buffers[k];src.playbackRate.value=rate;filter.type='lowpass';filter.frequency.value=k==='dirt'?590:k==='gravel'?3000:2400;gain.gain.value=(k==='gravel'?.23:.30)*w;src.connect(filter);filter.connect(gain);gain.connect(audio.master);if(p<.58)gain.connect(audio.echo);src.start(t);src.onended=()=>{src.disconnect();gain.disconnect();filter.disconnect();};}return true;}
